const MONTH_ORDER = (d: string) => {
  const m = d.match(/(\d+)(?:–\d+)?\s*(Mar|Apr)/);
  if (!m) return 0;
  return (m[2] === 'Mar' ? 0 : 100) + Number(m[1]);
};
function calKey(d: string): number {
  // "30–31 Mar", "Thu 1 Apr", "12–25 Apr" -> ordering by first day
  const m = d.match(/(\d+)(?:–\d+)?\s*(Mar|Apr)/);
  return m ? MONTH_ORDER(d) + (/–/.test(d) ? 0.5 : 0) : 0;
}
